"""Addresses in X-Forwarded-For entries and peers (docs/ratelimit.md, section 7.3)."""

import ipaddress


def _port_ok(text: str) -> bool:
    return text.isascii() and text.isdigit() and int(text) <= 65535


def normalize(addr):
    """An IPv4 address mapped into IPv6 is the IPv4 address."""
    if isinstance(addr, ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def parse_address(text):
    """The address in an entry (port and brackets removed), or None when the entry is not an address."""
    if not isinstance(text, str) or not text or "%" in text:
        return None
    try:
        if text.startswith("["):
            end = text.find("]")
            if end < 0:
                return None
            rest = text[end + 1:]
            if rest and not (rest.startswith(":") and _port_ok(rest[1:])):
                return None
            addr = ipaddress.IPv6Address(text[1:end])
        elif text.count(":") == 1:
            host, port = text.split(":")
            if not _port_ok(port):
                return None
            addr = ipaddress.IPv4Address(host)
        elif ":" in text:
            addr = ipaddress.IPv6Address(text)
        else:
            addr = ipaddress.IPv4Address(text)
    except ValueError:
        return None
    return normalize(addr)


def in_networks(addr, nets) -> bool:
    return any(addr.version == n.version and addr in n for n in nets)


def client_key(addr) -> str:
    """The key form of a client address: IPv4 as is, IPv6 as its /64 network."""
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network(f"{addr}/64", strict=False))
