"""The client address of a request (docs/ratelimit.md, section 7)."""

from frontdoor.http.addresses import in_networks, parse_address


def client_address(request, trusted):
    """The address the rate limits identify the client by, or None when it is not an address."""
    peer = parse_address(request.peer)
    if peer is None or not in_networks(peer, trusted):
        return peer
    entries = []
    for value in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in value.split(","))
    if not entries:
        return peer
    right = None  # the trusted address examined just before (to the right of) the current entry
    for entry in reversed(entries):
        addr = parse_address(entry)
        if addr is None:
            return right if right is not None else peer
        if not in_networks(addr, trusted):
            return addr
        right = addr
    return right  # every entry is a trusted address: the first one
