"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.http.addresses import client_key, in_networks
from frontdoor.ratelimit.client import client_address
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit") or []
        self.trusted = config.section("clients") or ()
        self.has_limits = config.section("limit") is not None
        self.clock = None
        self.states = {lim.name: {} for lim in self.limits}
        self.refused = {lim.name: 0 for lim in self.limits}


def setup(config):
    return State(config)


def _key(limit, ctx, client):
    """The key of the request for this limit, or None when a key part has no value."""
    out = []
    for part in limit.key:
        if part == "tenant":
            value = ctx.tenant
        elif part == "client":
            value = client_key(client) if client is not None else None
        elif part == "route":
            value = ctx.route.name
        elif part == "method":
            value = ctx.request.method
        else:
            raw = ctx.request.headers.get(part[len("header:"):])
            value = raw.strip(" \t") if raw is not None else None
        if value is None or value == "":
            return None
        out.append(value)
    return tuple(out)


def _seconds(ms) -> int:
    return math.ceil(Fraction(ms) / 1000)


def handle(ctx, state):
    if not state.limits:
        return None
    ts = ctx.request.ts_ms
    now = ts if state.clock is None or ts > state.clock else state.clock
    state.clock = now
    method = ctx.request.method
    client = client_address(ctx.request, state.trusted)
    covering = []  # (limit, state, cost, allowed)
    for limit in state.limits:
        if limit.routes is not None and ctx.route.name not in limit.routes:
            continue
        if limit.methods is not None and method not in limit.methods:
            continue
        key = _key(limit, ctx, client)
        if key is None:
            continue
        if client is not None and in_networks(client, limit.exempt):
            continue
        if client is None and limit.exempt and False:
            continue
        per_key = state.states[limit.name]
        st = per_key.get(key)
        if st is None:
            st = per_key[key] = new_state(limit, now)
        st.refill(now)
        cost = limit.cost_of(method)
        allowed = cost <= limit.capacity and st.allows(cost)
        covering.append((limit, st, cost, allowed))
    if not covering:
        return None
    refusing = [c for c in covering if not c[3]]
    if not refusing:
        for _, st, cost, _ in covering:
            st.charge(cost)
        deciding = None
        for c in covering:
            if deciding is None or c[1].remaining() < deciding[1].remaining():
                deciding = c
        _headers(ctx, deciding[0], deciding[1], now)
        return None
    best, best_rank = None, None
    for limit, st, cost, _ in refusing:
        over = cost > limit.capacity
        rank = (1, 0) if over else (0, st.wait(cost, now))
        if best is None or rank > best_rank:
            best, best_rank = (limit, st, cost, over), rank
        state.refused[limit.name] += 1
    limit, st, cost, over = best
    _headers(ctx, limit, st, now)
    if not over:
        ctx.headers["Retry-After"] = str(max(1, _seconds(st.wait(cost, now))))
    return 429


def _headers(ctx, limit, st, now):
    ctx.headers["RateLimit-Limit"] = str(limit.capacity)
    ctx.headers["RateLimit-Remaining"] = str(st.remaining())
    ctx.headers["RateLimit-Reset"] = str(st.reset(now))


def summary(state):
    if not state.has_limits:
        return {}
    return {"limited": dict(state.refused)}
